        branch_enable : out std_logic;
        jump : out std_logic;
        jalr : out std_logic;
        wb_select : out std_logic_vector(1 downto 0);
        muldiv_op : out std_logic
    );
end entity decoder;

architecture rtl of decoder is
begin
    process(all)
    begin
        reg_write     <= '0';
        mem_write     <= '0';
        alu_src_a_pc  <= '0';
        alu_src_b_imm <= '0';
        alu_control   <= "0000";
        branch_enable <= '0';
        jump          <= '0';
