                        when "001" => alu_control <= "0010";
                        when "010" => alu_control <= "0011";
                        when "011" => alu_control <= "0100";
                        when "100" => alu_control <= "0101";
                        when "101" => alu_control <= "0110";
                        when "110" => alu_control <= "1000";
                        when others => alu_control <= "1001";
                    end case;
                elsif instr(31 downto 25) = "0100000" then
                    if instr(14 downto 12) = "000" then
                        reg_write <= '1';
                        alu_control <= "0001";
                    elsif instr(14 downto 12) = "101" then
                        reg_write <= '1';
                        alu_control <= "0111";
                    end if;
                end if;

            when "0010011" => -- OP-IMM
                case instr(14 downto 12) is
                    when "000" =>
                        reg_write <= '1';
                        alu_src_b_imm <= '1';
                        alu_control <= "0000";
                    when "001" =>
                        if instr(31 downto 25) = "0000000" then
                            reg_write <= '1';
                            alu_src_b_imm <= '1';
                            alu_control <= "0010";
                        end if;
                    when "010" =>
                        reg_write <= '1';
                        alu_src_b_imm <= '1';
                        alu_control <= "0011";
                    when "011" =>
                        reg_write <= '1';
                        alu_src_b_imm <= '1';
                        alu_control <= "0100";
                    when "100" =>
                        reg_write <= '1';
                        alu_src_b_imm <= '1';
                        alu_control <= "0101";
                    when "101" =>
                        if instr(31 downto 25) = "0000000" then
                            reg_write <= '1';
                            alu_src_b_imm <= '1';
                            alu_control <= "0110";
                        elsif instr(31 downto 25) = "0100000" then
                            reg_write <= '1';
                            alu_src_b_imm <= '1';
                            alu_control <= "0111";
                        end if;
                    when "110" =>
                        reg_write <= '1';
                        alu_src_b_imm <= '1';
                        alu_control <= "1000";
                    when "111" =>
                        reg_write <= '1';
                        alu_src_b_imm <= '1';
                        alu_control <= "1001";
                    when others =>
                        null;
                end case;

            when "0000011" => -- Loads
                case instr(14 downto 12) is
                    when "000" | "001" | "010" | "100" | "101" =>
                        reg_write <= '1';
                        alu_src_b_imm <= '1';
                        alu_control <= "0000";
                        wb_select <= "01";
                    when others =>
