            when "1100011" => -- Conditional branches
                case instr(14 downto 12) is
                    when "000" =>
                        branch_enable <= '1';
                        alu_control <= "0000";
                    when "001" =>
                        branch_enable <= '1';
                        alu_control <= "0001";
                    when "100" =>
                        branch_enable <= '1';
                        alu_control <= "0010";
                    when "101" =>
                        branch_enable <= '1';
                        alu_control <= "0011";
                    when "110" =>
                        branch_enable <= '1';
                        alu_control <= "0100";
                    when "111" =>
                        branch_enable <= '1';
                        alu_control <= "0101";
                    when others =>
                        null;
                end case;

            when "0110111" => -- LUI
                reg_write <= '1';
                alu_src_b_imm <= '1';
                alu_control <= "1010";

            when "0010111" => -- AUIPC
                reg_write <= '1';
                alu_src_a_pc <= '1';
                alu_src_b_imm <= '1';
                alu_control <= "0000";

            when "1101111" => -- JAL
                reg_write <= '1';
                alu_src_a_pc <= '1';
                alu_src_b_imm <= '1';
                jump <= '1';
                wb_select <= "10";

            when "1100111" => -- JALR
