                    reg_write <= '1';
                    alu_src_b_imm <= '1';
                    jump <= '1';
                    jalr <= '1';
                    wb_select <= "10";
                    alu_control <= "0000";
                end if;

            when others =>
                null;
        end case;
    end process;
end architecture rtl;
